import React, { useState } from "react";
import { Box, Typography, TextField, Button, Chip, Divider } from "@mui/material";
import { ZB_COLORS } from "./theme";

const SectionCard = ({ children, sx }) => (
  <Box sx={{ background: ZB_COLORS.navyMid, border: `0.5px solid ${ZB_COLORS.border}`, borderRadius: "12px", p: 3, mb: 2, ...sx }}>
    {children}
  </Box>
);

// ─── FORUM ────────────────────────────────────────────────────────────────────
export function Forum() {
  const [topics, setTopics] = useState([
    { id: 1, title: "How to break into Zambian fintech?", content: "Looking for advice on entering the fintech space as a fresh graduate.", replies: [], timestamp: new Date() },
    { id: 2, title: "Best resources for supply chain beginners", content: "Can anyone share good free courses for procurement?", replies: [], timestamp: new Date() },
  ]);
  const [newTitle, setNewTitle] = useState("");
  const [newContent, setNewContent] = useState("");
  const [replyText, setReplyText] = useState({});

  const handlePost = () => {
    if (!newTitle.trim() || !newContent.trim()) return;
    setTopics([{ id: Date.now(), title: newTitle, content: newContent, replies: [], timestamp: new Date() }, ...topics]);
    setNewTitle(""); setNewContent("");
  };

  const handleReply = (topicId) => {
    if (!replyText[topicId]?.trim()) return;
    setTopics(topics.map(t => t.id === topicId ? { ...t, replies: [...t.replies, { text: replyText[topicId], timestamp: new Date() }] } : t));
    setReplyText({ ...replyText, [topicId]: "" });
  };

  return (
    <Box sx={{ maxWidth: 860, mx: "auto", px: { xs: 2, md: 4 }, py: { xs: 4, md: 6 } }}>
      <Typography sx={{ fontSize: "0.72rem", textTransform: "uppercase", letterSpacing: "0.1em", color: ZB_COLORS.gold, fontWeight: 600, mb: 1, fontFamily: "DM Sans" }}>Community</Typography>
      <Typography variant="h4" sx={{ color: "#fff", mb: 0.5 }}>Forum & discussion</Typography>
      <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 4 }}>Start a conversation, share ideas, or ask questions.</Typography>

      <SectionCard>
        <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", mb: 2 }}>Start a new topic</Typography>
        <TextField label="Title" fullWidth value={newTitle} onChange={e => setNewTitle(e.target.value)} sx={{ mb: 2 }} />
        <TextField label="Content" fullWidth multiline minRows={2} value={newContent} onChange={e => setNewContent(e.target.value)} sx={{ mb: 2 }} />
        <Button variant="contained" onClick={handlePost} disabled={!newTitle.trim() || !newContent.trim()}>Post topic</Button>
      </SectionCard>

      {topics.map(topic => (
        <SectionCard key={topic.id}>
          <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", mb: 0.5 }}>{topic.title}</Typography>
          <Typography sx={{ fontSize: "0.75rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 1 }}>{topic.timestamp.toLocaleDateString()}</Typography>
          <Typography sx={{ color: "rgba(255,255,255,0.75)", fontFamily: "DM Sans", fontSize: "0.875rem", mb: 2 }}>{topic.content}</Typography>
          {topic.replies.length > 0 && (
            <Box sx={{ pl: 2, borderLeft: `2px solid ${ZB_COLORS.border}`, mb: 2 }}>
              {topic.replies.map((r, i) => (
                <Box key={i} sx={{ mb: 1 }}>
                  <Typography sx={{ fontSize: "0.75rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>You · {r.timestamp.toLocaleTimeString()}</Typography>
                  <Typography sx={{ color: "rgba(255,255,255,0.8)", fontFamily: "DM Sans", fontSize: "0.875rem" }}>{r.text}</Typography>
                </Box>
              ))}
            </Box>
          )}
          <Box sx={{ display: "flex", gap: 1 }}>
            <TextField placeholder="Reply…" size="small" fullWidth value={replyText[topic.id] || ""} onChange={e => setReplyText({ ...replyText, [topic.id]: e.target.value })} />
            <Button variant="contained" size="small" onClick={() => handleReply(topic.id)} disabled={!replyText[topic.id]?.trim()}>Reply</Button>
          </Box>
        </SectionCard>
      ))}
    </Box>
  );
}

export default Forum;
